"node -e '
const fs = require("fs");
const crypto = require("crypto");
const { execSync } = require("child_process");

const files = [
  "crush.wasm",
  "hls-proxy.js",
  "http-client.js",
  "index.js",
  "package.json",
  "resolver.js",
  "services.json"
];

console.log("=== COMPARING SHA-256 OF DISK VS IPK DATA PAYLOAD ===");
let allMatch = true;

for (const f of files) {
  const diskPath = "services/com.cinejoy.tv.service/" + f;
  const diskBuf = fs.readFileSync(diskPath);
  const diskHash = crypto.createHash("sha256").update(diskBuf).digest("hex");
  const diskSize = diskBuf.length;

  const ipkBuf = execSync("ar -p dist/com.cinejoy.tv_1.0.0_all.ipk data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/" + f + " -O");
  const ipkHash = crypto.createHash("sha256").update(ipkBuf).digest("hex");
  const ipkSize = ipkBuf.length;

  const match = (diskHash === ipkHash && diskSize === ipkSize);
  if (!match) allMatch = false;

  console.log(`File: ${f}`);
  console.log(`  Disk: ${diskSize} bytes | SHA256: ${diskHash}`);
  console.log(`  IPK:  ${ipkSize} bytes | SHA256: ${ipkHash}`);
  console.log(`  Match: ${match ? "YES" : "NO"}`);
}

console.log("=====================================================");
console.log(`All 7 files match byte-for-byte: ${allMatch ? "PASS" : "FAIL"}`);

// Check crush.wasm magic header
const wasmBuf = fs.readFileSync("services/com.cinejoy.tv.service/crush.wasm");
const magic = wasmBuf.slice(0, 4);
const isMagicValid = magic[0] === 0x00 && magic[1] === 0x61 && magic[2] === 0x73 && magic[3] === 0x6d;
console.log(`crush.wasm magic header \\0asm: ${isMagicValid ? "VALID" : "INVALID"}`);
'"

