"node -e '
const http = require("http");

async function check() {
  const pages = await new Promise(resolve => {
    http.get("http://192.168.1.15:9998/json", res => {
      let d = "";
      res.on("data", c => d += c);
      res.on("end", () => resolve(JSON.parse(d)));
    });
  });
  const target = pages.find(p => p.url && p.url.includes("com.cinejoy.tv"));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  ws.onopen = () => {
    ws.send(JSON.stringify({
      id: 1,
      method: "Runtime.evaluate",
      params: {
        expression: `(() => {
          CinejoyApp.switchView("home");
          const heroDetails = document.getElementById("hero-details-btn");
          SpatialNav.setFocus(heroDetails);
          const f0 = SpatialNav.getCurrentFocus();

          const rect0 = heroDetails.getBoundingClientRect();

          // Let SpatialNav move down
          SpatialNav.move("down");
          const f1 = SpatialNav.getCurrentFocus();
          const rect1 = f1 ? f1.getBoundingClientRect() : null;

          SpatialNav.move("down");
          const f2 = SpatialNav.getCurrentFocus();
          const rect2 = f2 ? f2.getBoundingClientRect() : null;

          return JSON.stringify({
            f0: f0 ? (f0.id || f0.className) : null,
            rect0,
            f1: f1 ? (f1.id || f1.className || f1.getAttribute("data-title")) : null,
            rect1,
            f2: f2 ? (f2.id || f2.className || f2.getAttribute("data-title")) : null,
            rect2
          });
        })()`,
        returnByValue: true
      }
    }));
  };
  ws.onmessage = (e) => {
    console.log("Details down:", JSON.parse(e.data).result.result.value);
    ws.close();
  };
}
check();
'"

